const SOURCE_EXTENSIONS = new Set(["mp4", "mov", "m4v", "mpg", "mpeg", "ts", "mkv", "webm"]);
export const DEV_SESSION_SECRET = "dev-insecure-session-secret";

function safeEqual(a: string, b: string): boolean {
