  app.post("/v1/creatives", async (req, reply) => {
    const b = (req.body ?? {}) as Record<string, unknown>;
    if (!b.campaign_id || !b.name || typeof b.duration !== "number") {
      return reply.code(400).send({ error: "campaign_id, name and numeric duration are required" });
    }
    const id = (b.id as string) || `cr_${randomUUID().slice(0, 8)}`;
    try {
      await creativesRepo.insertCreative(pool, {
        id,
        campaignId: String(b.campaign_id),
        name: String(b.name),
        duration: b.duration,
        status: (b.status as CreativeStatus) ?? "ready",
        priority: (b.priority as number) ?? 0,
        weight: (b.weight as number) ?? 100,
      });
    } catch {
      return reply.code(400).send({ error: "invalid campaign_id — creative must reference an existing campaign" });
    }
    return reply.code(201).send(await creativesRepo.getCreative(pool, id));
  });

  // Upload a creative's source media (PRD §14). Stores the file and marks the
  // creative `uploaded`; the offline worker transcodes it. ffmpeg never runs
  // here — this endpoint only accepts + stores the source.
  app.post("/v1/creatives/:id/source", async (req, reply) => {
    if (!store) return reply.code(501).send({ error: "uploads not configured (no object store)" });
    const { id } = req.params as { id: string };
    if (!(await creativesRepo.getCreative(pool, id))) {
      return reply.code(404).send({ error: "creative not found — create it first" });
    }

    const file = await req.file();
    if (!file) return reply.code(400).send({ error: "a file field is required" });

    const ext = (file.filename?.split(".").pop() ?? "").toLowerCase();
    if (!SOURCE_EXTENSIONS.has(ext)) {
      return reply.code(400).send({ error: `unsupported source type .${ext}` });
    }

    let buffer: Buffer;
    try {
      buffer = await file.toBuffer();
    } catch {
      // @fastify/multipart throws when the file exceeds the configured limit.
      return reply.code(413).send({ error: "file too large" });
    }

    const sourceKey = `sources/creatives/${id}/source.${ext}`;
    await store.put(sourceKey, buffer);
    await creativesRepo.setCreativeSource(pool, id, sourceKey);
    await creativesRepo.setCreativeStatus(pool, id, "uploaded");

    return reply.code(202).send({ creative_id: id, source_key: sourceKey, bytes: buffer.length, status: "uploaded" });
  });

  return app;
}

// Bootstrap from env when run directly.
if (import.meta.url === `file://${process.argv[1]}`) {
  const { createPool, createRedis, RedisPodCache } = await import("@ssai/persistence");
  const { createObjectStoreFromEnv } = await import("@ssai/storage");
  const pool = createPool();
  const podCache = new RedisPodCache(createRedis());
  const store = await createObjectStoreFromEnv();
  const app = buildServer({ pool, podCache, store });
  app.listen({ port: Number(process.env.CONTROL_PLANE_PORT ?? 4000), host: "0.0.0.0" }).catch((err) => {
    app.log.error(err);
    process.exit(1);
  });
